(4049703, 579012, 66597, '<td valign="top">Nice capture, though I think a closer, tighter crop would serve you well here.</td>', 'Nice capture, though I think a closer, tighter crop would serve you well here.', '2007-09-02 09:46:26.000000', NULL, 1),
(4049705, 571109, 67258, '<td valign="top">The small size makes it difficult to appraise this photo.  Check out <a href="//www.dpchallenge.com/tutorial.php?TUTORIAL_ID=26" rel="nofollow" target="_blank">this tutorial</a> for help in preparing photos for challenges.</td>', 'The small size makes it difficult to appraise this photo.  Check out this tutorial for help in preparing photos for challenges.', '2007-09-02 09:48:01.000000', NULL, 1),
(4049706, 578857, 67258, '<td valign="top">I like this - composition, colours, and lighting.</td>', 'I like this - composition, colours, and lighting.', '2007-09-02 09:48:56.000000', NULL, 1),
(4049707, 577237, 67258, '<td valign="top">Too bright for my taste  - makes me want to reach for my sunglasses!  Nice pose, though.</td>', 'Too bright for my taste  - makes me want to reach for my sunglasses!  Nice pose, though.', '2007-09-02 09:50:16.000000', NULL, 1),
