(4049711, 565752, 67258, '<td valign="top">This is lovely!  The yellow rubdekia flowers provide a lovely natural framing. Very good indeed.</td>', 'This is lovely!  The yellow rubdekia flowers provide a lovely natural framing. Very good indeed.', '2007-09-02 09:51:09.000000', NULL, 1),
(4049712, 576480, 69368, '<td valign="top">fantastic background</td>', 'fantastic background', '2007-09-02 09:51:35.000000', NULL, 1),
