(4054221, 579177, 67258, '<td valign="top">That certainly is chaotic - one photo, or a composite?  From an aesthetic perspective, I do find it too busy to be appealing.</td>', 'That certainly is chaotic - one photo, or a composite?  From an aesthetic perspective, I do find it too busy to be appealing.', '2007-09-03 19:17:32.000000', NULL, 1),
(4054227, 571019, 65468, '<td valign="top">Dramatic lighting but total out of focus</td>', 'Dramatic lighting but total out of focus', '2007-09-03 19:19:20.000000', NULL, 1),
(4054229, 579722, 67258, '<td valign="top">A basically good photograph, but somewhat overkill in post-processing.  Specifically, far too much neat image has removed the detail that is so important.</td>', 'A basically good photograph, but somewhat overkill in post-processing.  Specifically, far too much neat image has removed the detail that is so important.', '2007-09-03 19:20:16.000000', NULL, 1),
(4054233, 575860, 65468, '<td valign="top">Good moment would have voted higher if their feet were there.  It seems incomplete this crop</td>', 'Good moment would have voted higher if their feet were there.  It seems incomplete this crop', '2007-09-03 19:22:46.000000', NULL, 1),
(4054234, 567346, 67258, '<td valign="top">Not sure that the ''stars'' add anything to this - it is an extremely strong photo in its own right!</td>', 'Not sure that the ''stars'' add anything to this - it is an extremely strong photo in its own right!', '2007-09-03 19:23:32.000000', NULL, 1),
(4054244, 579831, 67258, '<td valign="top">Oh yes,I do like this!</td>', 'Oh yes,I do like this!', '2007-09-03 19:28:14.000000', NULL, 1),
(4054259, 579181, 65468, '<td valign="top">Great timing</td>', 'Great timing', '2007-09-03 19:37:31.000000', NULL, 1),
(4054265, 579203, 65468, '<td valign="top">I love portraits like this there is always such depth and story in the faces</td>', 'I love portraits like this there is always such depth and story in the faces', '2007-09-03 19:40:47.000000', NULL, 1),
(4054269, 577237, 65468, '<td valign="top">Beautiful lady but the color seems washed out to me.  Would like to see more skin tone and color depth.</td>', 'Beautiful lady but the color seems washed out to me.  Would like to see more skin tone and color depth.', '2007-09-03 19:44:20.000000', NULL, 1),
(4054272, 575713, 65468, '<td valign="top">Great B&amp;W image really like the windowing care to capture the full height of the tower on the right.  Well done</td>', 'Great B&W image really like the windowing care to capture the full height of the tower on the right.  Well done', '2007-09-03 19:46:33.000000', NULL, 1),
(4054277, 569983, 65468, '<td valign="top">Nice image good DOF and color sat</td>', 'Nice image good DOF and color sat', '2007-09-03 19:49:12.000000', NULL, 1),
(4054301, 579478, 65468, '<td valign="top">Well we are certainly color coordinated.  Great expression.</td>', 'Well we are certainly color coordinated.  Great expression.', '2007-09-03 20:02:20.000000', NULL, 1),
(4054303, 571028, 5912, '<td valign="top">Love the pattern of the clouds</td>', 'Love the pattern of the clouds', '2007-09-03 20:02:43.000000', NULL, 1),
(4054305, 573046, 5912, '<td valign="top">I think the subject could be isolated a little more</td>', 'I think the subject could be isolated a little more', '2007-09-03 20:03:08.000000', NULL, 1),
(4054306, 578562, 65468, '<td valign="top">Wonderful textures and image quality</td>', 'Wonderful textures and image quality', '2007-09-03 20:03:23.000000', NULL, 1),
(4054314, 568544, 83631, '<td valign="top">Makes me think of Magritte . . .</td>', 'Makes me think of Magritte . . .', '2007-09-03 20:06:15.000000', NULL, 1),
(4054315, 579512, 5912, '<td valign="top">Great focus on the closest eye. Composition and DOF are very good.</td>', 'Great focus on the closest eye. Composition and DOF are very good.', '2007-09-03 20:06:24.000000', NULL, 1),
(4054322, 567346, 65468, '<td valign="top">Rich tones amazing clarity for such a low light level.</td>', 'Rich tones amazing clarity for such a low light level.', '2007-09-03 20:08:07.000000', NULL, 1),
(4054338, 566565, 65468, '<td valign="top">In IMO the sun is totally wrong for the rest of the mood of the image.  Would have rated this much higher without it.</td>', 'In IMO the sun is totally wrong for the rest of the mood of the image.  Would have rated this much higher without it.', '2007-09-03 20:14:13.000000', NULL, 1),
(4054366, 575713, 51538, '<td valign="top">I''m not sure how you put this shot together (since the challenge is under expert rules) but I like the overall effect and composition.  Very satisfying. 8.</td>', 'I''m not sure how you put this shot together (since the challenge is under expert rules) but I like the overall effect and composition.  Very satisfying. 8.', '2007-09-03 20:26:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4054371, 579255, 51538, '<td valign="top">I always think the 720px images are more seductive to image grabbers... and viewing on my laptop necessitates scrolling.  I''m surely in the minority with such assumptions.  The bokeh is an enjoyable colour and the impressionistic composition is summery and pleasing. 9.</td>', 'I always think the 720px images are more seductive to image grabbers... and viewing on my laptop necessitates scrolling.  I''m surely in the minority with such assumptions.  The bokeh is an enjoyable colour and the impressionistic composition is summery and pleasing. 9.', '2007-09-03 20:28:24.000000', NULL, 1),
(4054374, 579386, 51538, '<td valign="top">Interesting coppery lustre and scene.  The composition and choice of frame works well for me. 8.</td>', 'Interesting coppery lustre and scene.  The composition and choice of frame works well for me. 8.', '2007-09-03 20:29:38.000000', NULL, 1),
(4054385, 576942, 51538, '<td valign="top">The metallic sheen and reflections evoke a certain surreal mood.  I like the placement of the subject and distant city. 8.</td>', 'The metallic sheen and reflections evoke a certain surreal mood.  I like the placement of the subject and distant city. 8.', '2007-09-03 20:32:07.000000', NULL, 1),
(4054387, 571423, 51538, '<td valign="top">Pretty image with nice rhythm.</td>', 'Pretty image with nice rhythm.', '2007-09-03 20:32:51.000000', NULL, 1),
(4054395, 575896, 51538, '<td valign="top">Reminds me of Portsmouth Harbour.  The colours and viewpoint are pleasant enough.</td>', 'Reminds me of Portsmouth Harbour.  The colours and viewpoint are pleasant enough.', '2007-09-03 20:34:25.000000', NULL, 1),
(4054398, 573216, 51538, '<td valign="top">Reminds me of days in the Green Mountains a week or two ago.  Our blackberries have now become plum and blackberry jam.</td>', 'Reminds me of days in the Green Mountains a week or two ago.  Our blackberries have now become plum and blackberry jam.', '2007-09-03 20:35:11.000000', NULL, 1),
(4054402, 576306, 51538, '<td valign="top">That''s a very lavender-coloured day there.  The colour shift seems pleasant enough as does the composition.</td>', 'That''s a very lavender-coloured day there.  The colour shift seems pleasant enough as does the composition.', '2007-09-03 20:36:46.000000', NULL, 1),
(4054413, 576563, 51538, '<td valign="top">Well put together and an interesting anthropomorphic story.  It''s a nice part of the countryside. 8.</td>', 'Well put together and an interesting anthropomorphic story.  It''s a nice part of the countryside. 8.', '2007-09-03 20:41:02.000000', NULL, 1),
(4054440, 578401, 76766, '<td valign="top">I really like this photo alot. I do wish she was looking up though. It would be nice to see more of her profile than her hair.</td>', 'I really like this photo alot. I do wish she was looking up though. It would be nice to see more of her profile than her hair.', '2007-09-03 20:54:50.000000', NULL, 1),
(4054597, 578722, 43463, '<td valign="top">Oh - my - gosh!!!! The lighting, the color tones and the composition is perfect! Love the colors, the sweep of the rock hill that leads up to the lone cypress, the ripples of the water, the clouds drifting along the sky, and that wonderful capture of the full moon in the far left corner. An excellent job all around. There is no advice to offer for you to improve on the image - it is exceptionally beautiful and enchanting. Great job - I expect to see this in the top 5.</td>', 'Oh - my - gosh!!!! The lighting, the color tones and the composition is perfect! Love the colors, the sweep of the rock hill that leads up to the lone cypress, the ripples of the water, the clouds drifting along the sky, and that wonderful capture of the full moon in the far left corner. An excellent job all around. There is no advice to offer for you to improve on the image - it is exceptionally beautiful and enchanting. Great job - I expect to see this in the top 5.', '2007-09-03 21:57:06.000000', NULL, 1),
(4054632, 573846, 43463, '<td valign="top">Wow, the yellows of the falling lemons REALLY pop off of the hot pink background. Love the sense of motion in some of them showing that there is movement rather than static action taking place in the shot. Skin tones are great. The smile and the slight breeze that blows on the model''s hair is a wonderful touch because it invokes the idea of happiness and taking an easy breezy approach to life which plays well into the title stating the old addage "If Life gives you lemons, make lemonade." The slightly pink hair is a good touch as well because it subtly plays back to that hot pink background. The main hues of bright yellows and hot pinks are bright and happy tones also perfect for the idea and mood you are trying to convey. My only critique - and a small one at that - is that I wish the composition did not crop or cut off a portion of the umbrella. It would be better if the composition had ALL of the main compositional elements within the frame.</td>', 'Wow, the yellows of the falling lemons REALLY pop off of the hot pink background. Love the sense of motion in some of them showing that there is movement rather than static action taking place in the shot. Skin tones are great. The smile and the slight breeze that blows on the model''s hair is a wonderful touch because it invokes the idea of happiness and taking an easy breezy approach to life which plays well into the title stating the old addage "If Life gives you lemons, make lemonade." The slightly pink hair is a good touch as well because it subtly plays back to that hot pink background. The main hues of bright yellows and hot pinks are bright and happy tones also perfect for the idea and mood you are trying to convey. My only critique - and a small one at that - is that I wish the composition did not crop or cut off a portion of the umbrella. It would be better if the composition had ALL of the main compositional elements within the frame.', '2007-09-03 22:04:51.000000', NULL, 1),
(4054682, 566418, 43463, '<td valign="top">Wow, talk about a picture that pops out at ya! You have taken that saying an embodied it in this image. And you have done an exceptional well job of it too.  I like how you ''curved'' the main photograph to add to the optical illusion of this being 3-D and popping out of the frame &amp; image. The span of the bridge comes out of the main frame and continues off into the left bottom corner giving the eye some leading lines that lead off to the vanishing point of the road in the top right hand side of the picture. The ''wall'' is a grey gradient that goes from light to dark horizontally - a good choice for it adds another dimensional aspect (rather than a flat one tone wall) as well as being complimentary without overpowering the main subject of this composition.</td>', 'Wow, talk about a picture that pops out at ya! You have taken that saying an embodied it in this image. And you have done an exceptional well job of it too.  I like how you ''curved'' the main photograph to add to the optical illusion of this being 3-D and popping out of the frame & image. The span of the bridge comes out of the main frame and continues off into the left bottom corner giving the eye some leading lines that lead off to the vanishing point of the road in the top right hand side of the picture. The ''wall'' is a grey gradient that goes from light to dark horizontally - a good choice for it adds another dimensional aspect (rather than a flat one tone wall) as well as being complimentary without overpowering the main subject of this composition.', '2007-09-03 22:13:59.000000', NULL, 1),
(4054712, 579514, 43463, '<td valign="top">Love the composition and colors on this photo. The sky is wonderful! I really like the fire-orange clouds to slow fade from navy to slate blue to gold lit sky. The colors are beautifully saturated (without it being too oversaturated)...very rich in tone from those lovely greens to the colors of the sky. I like how you composed the shot too. The wonderfully decorated mailbox stops our attention right before the eye goes back to the road whose leading lines lead the eye off into the horizon to then travel up to the sky.</td>', 'Love the composition and colors on this photo. The sky is wonderful! I really like the fire-orange clouds to slow fade from navy to slate blue to gold lit sky. The colors are beautifully saturated (without it being too oversaturated)...very rich in tone from those lovely greens to the colors of the sky. I like how you composed the shot too. The wonderfully decorated mailbox stops our attention right before the eye goes back to the road whose leading lines lead the eye off into the horizon to then travel up to the sky.', '2007-09-03 22:20:13.000000', NULL, 1),
(4054720, 567488, 76217, '<td valign="top">I''ll bet trying to get the reflections to match was a bitch.</td>', 'I''ll bet trying to get the reflections to match was a bitch.', '2007-09-03 22:21:55.000000', NULL, 1),
(4054740, 578838, 43463, '<td valign="top">The B&amp;W aspect really makes the textures on the petals of this closed blossom really stand out. One can almost reach out and visually touch the softness of the closed petals. The flower really stands out from the black background not to mention the calls the eye''s attention to the single waterdrop delicately hanging, ready to fall. This is a very minimalistic, clean and elegantly presented capture.</td>', 'The B&W aspect really makes the textures on the petals of this closed blossom really stand out. One can almost reach out and visually touch the softness of the closed petals. The flower really stands out from the black background not to mention the calls the eye''s attention to the single waterdrop delicately hanging, ready to fall. This is a very minimalistic, clean and elegantly presented capture.', '2007-09-03 22:26:30.000000', NULL, 1),
(4054741, 577834, 76217, '<td valign="top">I''ve got mixed feelings about the person being there. I think you did a good job of establishing scale without her - and unless I can better see her facial expression (which is very difficult due to the scale)she is almost a distraction.</td>', 'I''ve got mixed feelings about the person being there. I think you did a good job of establishing scale without her - and unless I can better see her facial expression (which is very difficult due to the scale)she is almost a distraction.', '2007-09-03 22:27:08.000000', NULL, 1),
(4054755, 576185, 76217, '<td valign="top">Odd juxtaposition. I''m not sure what I''m looking at. Perhaps a tidal bay of some sort? The pieces don''t seem to fit naturally.</td>', 'Odd juxtaposition. I''m not sure what I''m looking at. Perhaps a tidal bay of some sort? The pieces don''t seem to fit naturally.', '2007-09-03 22:31:16.000000', NULL, 1),
(4054824, 579832, 51538, '<td valign="top">I like the tint you selected and the composition. The back view implies the future to me and the forest along the way has been used as a metaphor both literary and visual.  9.</td>', 'I like the tint you selected and the composition. The back view implies the future to me and the forest along the way has been used as a metaphor both literary and visual.  9.', '2007-09-03 22:52:13.000000', NULL, 1),
(4054839, 577914, 28882, '<td valign="top">surreal and creative</td>', 'surreal and creative', '2007-09-03 22:56:28.000000', NULL, 1),
(4054846, 575636, 28882, '<td valign="top">credit for difficult shot, but i think it needs darker blacks and different composition.</td>', 'credit for difficult shot, but i think it needs darker blacks and different composition.', '2007-09-03 22:58:03.000000', NULL, 1),
(4054848, 579865, 28882, '<td valign="top">wouldn''t change a thing.</td>', 'wouldn''t change a thing.', '2007-09-03 22:58:28.000000', NULL, 1),
(4054854, 579726, 28882, '<td valign="top">nice colors, foreground a little dark</td>', 'nice colors, foreground a little dark', '2007-09-03 22:59:01.000000', NULL, 1),
(4054871, 579808, 28882, '<td valign="top">well... i''m personally not fond of the frame or the green in it and i think it is cropped to closely. also, i hate to keep nit-picking, but the horse seems to be leaning unnaturally to the left.  otherwise i think this is a beautiful subject with good lighting.</td>', 'well... i''m personally not fond of the frame or the green in it and i think it is cropped to closely. also, i hate to keep nit-picking, but the horse seems to be leaning unnaturally to the left.  otherwise i think this is a beautiful subject with good lighting.', '2007-09-03 23:03:14.000000', NULL, 1),
(4054878, 579892, 28882, '<td valign="top">i like the black background here and even though the light seems glaring it doesn''t bother me.  the only gripe i would have is i think either the hand or the face should be in clear focus depending which you want to emphasize.</td>', 'i like the black background here and even though the light seems glaring it doesn''t bother me.  the only gripe i would have is i think either the hand or the face should be in clear focus depending which you want to emphasize.', '2007-09-03 23:05:38.000000', NULL, 1),
(4054892, 579686, 66267, '<td valign="top">lol looks like a rush album cover</td>', 'lol looks like a rush album cover', '2007-09-03 23:08:41.000000', NULL, 1),
(4054935, 568248, 66267, '<td valign="top">Hello simms, this must be you- same yak from your fill the frame and same ferns from your bokeh :P<br/> <br/>Anyway, great shot!-9</td>', 'Hello simms, this must be you- same yak from your fill the frame and same ferns from your bokeh :P Anyway, great shot!-9', '2007-09-03 23:19:06.000000', NULL, 1),
(4055280, 576480, 7485, '<td valign="top">Interesting idea, but would work much better for me if I could really see her eyes.</td>', 'Interesting idea, but would work much better for me if I could really see her eyes.', '2007-09-04 01:48:08.000000', NULL, 1),
(4055300, 568794, 51793, '<td valign="top">I think you might be having a little bit of trouble resizing your images. If you need help let me know.</td>', 'I think you might be having a little bit of trouble resizing your images. If you need help let me know.', '2007-09-04 01:57:46.000000', NULL, 1),
(4055337, 566973, 80767, '<td valign="top">amazing picture and composition ... added as a favorite</td>', 'amazing picture and composition ... added as a favorite', '2007-09-04 02:19:44.000000', NULL, 1),
(4055350, 579266, 5912, '<td valign="top">Great leading line. I like it, but it lacks something dramatic or more visually interesting.</td>', 'Great leading line. I like it, but it lacks something dramatic or more visually interesting.', '2007-09-04 02:27:30.000000', NULL, 1),
(4055360, 578909, 5912, '<td valign="top">Love the technique. Some of the moons look out of the circular path. Would have loved a mo interesting foreground.</td>', 'Love the technique. Some of the moons look out of the circular path. Would have loved a mo interesting foreground.', '2007-09-04 02:30:29.000000', NULL, 1),
(4055366, 579213, 5912, '<td valign="top">Bad lighting and too much saturation pushing.</td>', 'Bad lighting and too much saturation pushing.', '2007-09-04 02:32:02.000000', NULL, 1),
(4055369, 576167, 5912, '<td valign="top">Interesting foreground, subject, and background. The only thing throwing me off is the differences in the clouds in the reflection vs. the ones in the sky, but that may have been intended based on the title.</td>', 'Interesting foreground, subject, and background. The only thing throwing me off is the differences in the clouds in the reflection vs. the ones in the sky, but that may have been intended based on the title.', '2007-09-04 02:33:16.000000', NULL, 1),
(4055373, 576942, 5912, '<td valign="top">Great composition. Would have liked to have seen the clouds/fog hover above the city instead of extending all of the way to street level</td>', 'Great composition. Would have liked to have seen the clouds/fog hover above the city instead of extending all of the way to street level', '2007-09-04 02:34:57.000000', NULL, 1),
(4055376, 579909, 5912, '<td valign="top">A little less DOF would be nice. Good colors and composition</td>', 'A little less DOF would be nice. Good colors and composition', '2007-09-04 02:35:53.000000', NULL, 1),
(4055415, 578909, 63503, '<td valign="top">Great image (10)</td>', 'Great image (10)', '2007-09-04 02:53:26.000000', NULL, 1),
(4055418, 579203, 63503, '<td valign="top">Striking image (10)</td>', 'Striking image (10)', '2007-09-04 02:54:50.000000', NULL, 1),
(4055419, 575714, 29269, '<td valign="top">... said one DPCer to another :-)<br/>This one has great lighting - it is hard to get such a good shot of this seemingly dark staircase. Neon blues and greens and reds... no harsh shadows anywhere. Very well executed shot. Bumping to 9...</td>', '... said one DPCer to another :-)This one has great lighting - it is hard to get such a good shot of this seemingly dark staircase. Neon blues and greens and reds... no harsh shadows anywhere. Very well executed shot. Bumping to 9...', '2007-09-04 02:56:32.000000', NULL, 1),
(4055421, 579051, 63503, '<td valign="top">Gorgeous image</td>', 'Gorgeous image', '2007-09-04 02:57:56.000000', NULL, 1),
(4055439, 568361, 29269, '<td valign="top">Nice! One thing that is off (at least for me) is that his and her eyes are not attracted by the same thing. Obviously, girl is more attracted to your camera than to whatever grabbed his attention. Also, great costume work on the Sparrow, and somewhat sloppy on the girl. Is that a Banana Republic shirt on her ?:-)</td>', 'Nice! One thing that is off (at least for me) is that his and her eyes are not attracted by the same thing. Obviously, girl is more attracted to your camera than to whatever grabbed his attention. Also, great costume work on the Sparrow, and somewhat sloppy on the girl. Is that a Banana Republic shirt on her ?:-)', '2007-09-04 03:10:06.000000', NULL, 1),
(4055443, 577335, 29269, '<td valign="top">Strange orientation choice... leaves viewers begging for more (on the left as well as on the right)</td>', 'Strange orientation choice... leaves viewers begging for more (on the left as well as on the right)', '2007-09-04 03:11:23.000000', NULL, 1),
(4055449, 574755, 29269, '<td valign="top">You''ve had two choices for what to put in focus... I''m not sure if the other way around would have been better. I like it this way, too. A story-telling photography at its best.</td>', 'You''ve had two choices for what to put in focus... I''m not sure if the other way around would have been better. I like it this way, too. A story-telling photography at its best.', '2007-09-04 03:13:11.000000', NULL, 1),
(4055462, 579923, 69776, '<td valign="top">Nice skys, very nice image, but feels like it could use something in the foreground</td>', 'Nice skys, very nice image, but feels like it could use something in the foreground', '2007-09-04 03:18:21.000000', NULL, 1),
(4055464, 577882, 69776, '<td valign="top">Nice BW, the blacks look a bit too black imo</td>', 'Nice BW, the blacks look a bit too black imo', '2007-09-04 03:18:44.000000', NULL, 1),
(4055465, 577595, 69776, '<td valign="top">Love the Ray of light, the rest feels a bit undersaturated to me Good Luck</td>', 'Love the Ray of light, the rest feels a bit undersaturated to me Good Luck', '2007-09-04 03:19:16.000000', NULL, 1),
(4055469, 576942, 69776, '<td valign="top">Wow nice image, the blend has been done well and with a purpose too, Good One</td>', 'Wow nice image, the blend has been done well and with a purpose too, Good One', '2007-09-04 03:19:51.000000', NULL, 1),
(4055474, 579285, 69776, '<td valign="top">Interesting... Ive no Idea why you would do this, it makes his front paws look very odd</td>', 'Interesting... Ive no Idea why you would do this, it makes his front paws look very odd', '2007-09-04 03:20:32.000000', NULL, 1),
(4055476, 578298, 69776, '<td valign="top">Looks a bit oversharpend and too much noise removal to me, but damn these buggers are hard to catch :)</td>', 'Looks a bit oversharpend and too much noise removal to me, but damn these buggers are hard to catch :)', '2007-09-04 03:21:16.000000', NULL, 1),
(4055480, 579478, 69776, '<td valign="top">A nice snap shot, perhaps it would have been better with her looking down at the flowers, Good luck</td>', 'A nice snap shot, perhaps it would have been better with her looking down at the flowers, Good luck', '2007-09-04 03:21:48.000000', NULL, 1),
(4055483, 579283, 69776, '<td valign="top">Nice selective blur, the composition looks a bit haphazard to me thou, Good luck</td>', 'Nice selective blur, the composition looks a bit haphazard to me thou, Good luck', '2007-09-04 03:22:31.000000', NULL, 1),
